def solve(nums):
    # Floyd's Tortoise and Hare algorithm to find the cycle's start (which is the repeated value)
    def find_repeated(nums):
        # Phase 1: Find a meeting point
        slow = nums[0]
        fast = nums[nums[0]]
        while slow != fast:
            slow = nums[slow]
            fast = nums[nums[fast]]

        # Phase 2: Find the start of the cycle
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

    return find_repeated(nums)

