def solve(n, edges, s, t):
    # Dijkstra's algorithm with a priority queue
    visited = set()
    heap = [(0, s)]  # (distance, node)

    while heap:
        dist, u = heapq.heappop(heap)
        if u == t:
            return dist
        if u in visited:
            continue
        visited.add(u)
        for v, w in get_edges(u, edges):
            if v not in visited:
                heapq.heappush(heap, (dist + w, v))

    return -1

def get_edges(u, edges):
    res = []
    for u_edge, v_edge, w_edge in edges:
        if u_edge == u:
            res.append((v_edge, w_edge))
    return res

