def solve(edges, n):
    def remove_edges(u, v):
        for i in range(len(edges)):
            if edges[i][0] == u and edges[i][1] == v:
                del edges[i]
                return
            if edges[i][0] == v and edges[i][1] == u:
                del edges[i]
                return

    def count_components():
        visited = [False] * n
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for j in range(len(edges)):
                        if edges[j][0] == node and not visited[edges[j][1]]:
                            visited[edges[j][1]] = True
                            stack.append(edges[j][1])
                        if edges[j][1] == node and not visited[edges[j][0]]:
                            visited[edges[j][0]] = True
                            stack.append(edges[j][0])
        return count

    for i in range(n):
        for j in range(i + 1, n):
            if i != j:
                remove_edges(i, j)
    return count_components()

def solve(edges, n):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            count += 1
            queue = deque([i])
            visited[i] = True
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

    return count

