def find_cycle(graph, n):
    visited = [False] * n
    parent = [-1] * n

    def dfs(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                parent[v] = u
                if dfs(v):
                    return True
            elif parent[u] != v:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i):
                return True
    return False

