    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0

    for u, v, w in edges:
        if dist[u][v] > w:
            dist[u][v] = w

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Find the minimum path from 0 to all nodes
    result = []
    for j in range(n):
        if dist[0][j] != INF:
            result.append(dist[0][j])
        else:
            result.append(-1)

    print(result)

