        for v, w in graph[u]:
            dist[u][v] = min(dist[u][v], w)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Find the minimum path from any node to any node with minimum total weight
    min_total = INF
    for i in range(n):
        for j in range(n):
            if dist[i][j] < min_total:
                min_total = dist[i][j]

    if min_total == INF:
        print(-1)
    else:
        print(min_total)

