import random

def solve(n, edges, seed=None):
    # Generate a random permutation of nodes to simulate avoiding man and house
    random.seed(seed)
    perm = list(range(n))
    random.shuffle(perm)

    # Build adjacency list, avoiding nodes that are in the permutation (i.e., avoiding man and house)
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if u not in perm and v not in perm:
            adj[u].append((v, w))

    # Function to perform BFS for shortest path
    def bfs(start):
        visited = [False] * n
        queue = [(start, 0)]
        visited[start] = True
        while queue:
            node, dist = queue.pop(0)
            if node == start:
                return dist
            for neighbor, weight in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, dist + weight))
        return float('inf')

    # Try all possible starting nodes to find the shortest path
    min_dist = float('inf')
    for i in range(n):
        dist = bfs(i)
        if dist < min_dist:
            min_dist = dist

    if min_dist == float('inf'):
        return -1
    else:
        return min_dist

